-- Admin deadline digest, wider checks
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_template_check";--> statement-breakpoint
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_subject_check";--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_template_check" CHECK ("notifications"."template" IN ('report_submitted', 'report_in_review', 'report_verified', 'report_unverifiable', 'report_rejected', 'report_merged', 'report_forwarded', 'issue_refer', 'issue_escalate', 'issue_record_response', 'issue_mark_in_progress', 'issue_claim_resolved', 'issue_confirm_resolved', 'issue_reopen', 'issue_mark_not_competent', 'issue_mark_not_followed_up', 'issue_close', 'issue_published', 'complaint_received', 'complaint_decided', 'complaint_appeal_decided', 'demand_publish', 'demand_close', 'demand_reopen', 'demand_update', 'referral_deadline')) NOT VALID;--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_subject_check" CHECK (num_nonnulls("notifications"."report_id", "notifications"."issue_id", "notifications"."complaint_id", "notifications"."demand_id") = CASE WHEN "notifications"."template" IN ('referral_deadline') THEN 0 ELSE 1 END) NOT VALID;
